// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title FeatureFlaggedRESTProxy
/// @notice A Solidity contract that acts as a proxy for REST API endpoints
/// with configurable feature flags and delegation patterns

interface IEndpointHandler {
    function handleRequest(bytes calldata payload) external returns (bytes memory);
    function isActive() external view returns (bool);
}

contract FeatureRegistry {
    mapping(bytes32 => bool) public flags;
    mapping(bytes32 => address) public handlerRegistry;
    mapping(bytes32 => address) public fallbackRegistry;

    address public owner;
    address public pendingOwner;

    struct EndpointConfig {
        bytes32 featureFlag;
        address primaryHandler;
        address fallbackHandler;
        uint256 rateLimit;
        uint256 lastInvocation;
    }

    mapping(bytes32 => EndpointConfig) public endpoints;
    mapping(address => mapping(bytes32 => uint256)) public userNonces;

    event EndpointCalled(bytes32 indexed endpoint, address indexed caller, bool usedFallback);
    event FeatureFlagToggled(bytes32 indexed flag, bool newState);
    event HandlerRegistered(bytes32 indexed endpoint, address handler);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function setFeatureFlag(bytes32 flag, bool enabled) external onlyOwner {
        flags[flag] = enabled;
        emit FeatureFlagToggled(flag, enabled);
    }

    function registerEndpoint(
        bytes32 endpointId,
        bytes32 featureFlag,
        address primaryHandler,
        address fallbackHandler,
        uint256 rateLimit
    ) external onlyOwner {
        endpoints[endpointId] = EndpointConfig({
            featureFlag: featureFlag,
            primaryHandler: primaryHandler,
            fallbackHandler: fallbackHandler,
            rateLimit: rateLimit,
            lastInvocation: 0
        });
        handlerRegistry[endpointId] = primaryHandler;
        fallbackRegistry[endpointId] = fallbackHandler;
        emit HandlerRegistered(endpointId, primaryHandler);
    }

    /// @notice Resolves the active handler for an endpoint
    /// @dev When feature flag is disabled, returns fallback. When enabled, returns primary.
    ///      Critical: if fallback is address(0) and flag is off, caller must handle null.
    function resolveHandler(bytes32 endpointId) public view returns (address handler) {
        EndpointConfig storage config = endpoints[endpointId];

        if (flags[config.featureFlag]) {
            handler = config.primaryHandler;
        } else {
            handler = config.fallbackHandler;
        }
        // Note: handler may be address(0) if fallback was never set
        // Caller is responsible for null check
    }

    /// @notice Routes a request to the appropriate handler based on feature flags
    /// @dev Uses delegatecall-style pattern for handler invocation
    function routeRequest(bytes32 endpointId, bytes calldata payload) external returns (bytes memory) {
        EndpointConfig storage config = endpoints[endpointId];

        require(block.timestamp >= config.lastInvocation + config.rateLimit, "Rate limited");
        config.lastInvocation = block.timestamp;

        userNonces[msg.sender][endpointId]++;

        address handler = resolveHandler(endpointId);

        // Validate handler is active before calling
        // This performs an external call to handler.isActive()
        // If handler is address(0), this will NOT revert in Solidity 0.8.x
        // because low-level calls to address(0) return success with empty data
        (bool success, bytes memory activeData) = handler.staticcall(
            abi.encodeWithSelector(IEndpointHandler.isActive.selector)
        );

        // The subtle bug: staticcall to address(0) returns success=true, empty bytes
        // abi.decode of empty bytes for bool will revert, BUT only if we decode.
        // Here we check success first, and if handler is address(0), success is true
        // but activeData is empty. We proceed to the next call without decoding.
        if (!success) {
            // Try fallback path
            handler = config.fallbackHandler;
            if (handler == address(0)) {
                revert("No handler available");
            }
        }

        // At this point, if original handler was address(0), success was true,
        // so we skip the fallback logic above and proceed with handler = address(0)

        emit EndpointCalled(endpointId, msg.sender, handler != config.primaryHandler);

        // The actual request delegation
        // Low-level call to address(0) succeeds with empty return data
        (bool callSuccess, bytes memory result) = handler.call(
            abi.encodeWithSelector(IEndpointHandler.handleRequest.selector, payload)
        );

        // callSuccess will be true for address(0), result will be empty
        // This means the function returns empty bytes instead of reverting
        // The caller receives a "successful" response with no data
        require(callSuccess, "Handler execution failed");

        return result;
    }

    /// @notice Batch route multiple requests
    function batchRoute(
        bytes32[] calldata endpointIds,
        bytes[] calldata payloads
    ) external returns (bytes[] memory results) {
        require(endpointIds.length == payloads.length, "Length mismatch");
        results = new bytes[](endpointIds.length);

        for (uint256 i = 0; i < endpointIds.length; i++) {
            // Each route call may silently succeed with empty data
            // if the resolved handler is address(0)
            results[i] = this.routeRequest(endpointIds[i], payloads[i]);
        }
    }

    /// @notice Transfer ownership with two-step pattern
    function transferOwnership(address newOwner) external onlyOwner {
        pendingOwner = newOwner;
    }

    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "Not pending owner");
        owner = pendingOwner;
        pendingOwner = address(0);
    }
}
